/**
 * CUSTOMER CONFIRMATION + TRACKING FINAL v1 : exporté pour que
 * `resolveLang` (app/track/[orderId]/page.tsx) dérive la liste des
 * langues RÉELLEMENT prises en charge depuis cette SEULE autorité
 * (`Object.keys(DICTS)`), jamais une seconde liste littérale
 * dupliquée et potentiellement divergente.
 */
/**
 * Dictionnaire NÉERLANDAIS — TOUJOURS PARTIEL, par construction.
 *
 * Pourquoi partiel, et pourquoi c'est sûr : `translate()` replie clé par
 * clé (`dict[key] ?? fr[key] ?? key`), jamais dictionnaire par
 * dictionnaire. Une clé absente d'ici rend donc EXACTEMENT ce qu'elle
 * rendait avant — le français — et les clés présentes rendent le
 * néerlandais demandé par leur mandat. Aucun texte n'est inventé :
 * traduire les ~900 clés restantes de l'interface est un lot de
 * traduction à part entière, pas un effet de bord d'un lot produit.
 *
 * Ce dictionnaire contient exactement deux apports, et rien d'autre :
 *
 *   1. STOREFRONT ORDER HELP WORDING v1 — `deliveryConditionsTitle`,
 *      le libellé de la cartouche vitrine.
 *
 *   2. CSDJ-BO-1 (issue #149, « Rendre l'éditeur Mise à disposition
 *      entièrement fonctionnel ») — les clés de l'ÉCRAN « Mise à
 *      disposition » et de la navigation qui l'encadre, parce que ce
 *      mandat-là exige explicitement un « affichage accessible, mobile,
 *      FR/EN/AR/NL ». Le périmètre est mesuré, pas estimé : ce sont les
 *      clés RÉELLEMENT lues par app/dashboard/availability/page.tsx et
 *      par components/dashboard/DashboardNav.tsx, et aucune autre — un
 *      établissement néerlandophone voit donc cet écran-là entièrement
 *      en néerlandais, et le reste de l'interface exactement comme
 *      avant, en français.
 *
 * `LANGUAGES` n'est PAS élargi : cette liste pilote le sélecteur de
 * langue de l'interface marchande, et y ajouter NL annoncerait une
 * interface néerlandaise complète qui n'existe pas. NL reste ce qu'il est
 * aujourd'hui — une langue du catalogue `supported_languages`, activable
 * par établissement (voir le commentaire de `Lang` plus haut).
 *
 * CONSÉQUENCE ASSUMÉE, documentée depuis STOREFRONT ORDER HELP WORDING
 * v1 : `resolveLangFromParam("nl")` rend « nl » au lieu de se replier sur
 * « fr », puisque sa seule autorité est `Object.keys(DICTS)`. Le texte
 * rendu reste inchangé pour toute clé absente d'ici (repli français par
 * clé).
 */
